def _stress_map(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack([np.ones(len(raw)), raw]), cal['true_channel_loads'], rcond=None)[0].sum(axis=1)

def _chamber_response(group, x, dt, times, taus, theta):
    (curves, rates) = _design(group, x, dt, times, taus)
    drift = rates[:, 2:] @ theta[2:]
    return (group['strain_0'][:, None] + curves[:, :, :2] @ theta[:2] + drift[:, None] * -np.expm1(-times), rates @ theta)
